local menu={}local _BASE=""if shell then local prog=shell.getRunningProgram()local progDir=fs.getDir(prog)_BASE=(progDir~=""and progDir~=".")and(progDir.."/")or""end local function assetPath(rel)return _BASE..rel end local CHARACTERS={{id="drnightheart",name="Dr Nightheart",nfp="CCZombies/characters/DrNightheart.nfp"},{id="arissnightheart",name="Ariss Nightheart",nfp="CCZombies/characters/Ariss_Nightheart.nfp"},{id="alicee",name="Alice E",nfp="CCZombies/characters/AliceE.nfp"},{id="bayard",name="Bayard",nfp="CCZombies/characters/bayard.nfp"},}local cachedImages={}local function loadImage(path)if cachedImages[path]then return cachedImages[path]end local full=assetPath(path)if fs.exists(full)then local img=paintutils.loadImage(full)if img then cachedImages[path]=img return img end end return nil end local function nfpIndent(img)local minIndent=math.huge for iy=1,#img do local row=img[iy]for ix=1,#row do if row[ix]and row[ix]~=0 then if ix-1<minIndent then minIndent=ix-1 end break end end end return(minIndent==math.huge)and 0 or minIndent end local function nfpRight(img)local maxRight=0 for iy=1,#img do local row=img[iy]for ix=#row,1,-1 do if row[ix]and row[ix]~=0 then if ix>maxRight then maxRight=ix end break end end end return maxRight end local function drawImage(img,x,y,xSkip)if not img then return end xSkip=xSkip or 0 local oldBg=term.getBackgroundColor()local oldFg=term.getTextColor()for iy=1,#img do local row=img[iy]for ix=xSkip+1,#row do local color=row[ix]if color and color~=0 then term.setCursorPos(x+(ix-xSkip)-1,y+iy-1)term.setBackgroundColor(color)term.write(" ")end end end term.setBackgroundColor(oldBg)term.setTextColor(oldFg)end local function drawLogo(startY)local img=loadImage("CCZombies/logo.nfp")local w=term.getSize()if img then local indent=nfpIndent(img)local rightPx=nfpRight(img)local visW=rightPx-indent local logoX=math.max(1,math.floor((w-visW)/2)+1)drawImage(img,logoX,startY,indent)return#img else term.setCursorPos(1,startY)term.setTextColor(colors.red)term.clearLine()local title="CC: ZOMBIES"term.setCursorPos(math.max(1,math.floor((w-#title)/2)+1),startY)term.write(title)return 1 end end local function scrollMenu(cfg)local function itemHeight(item)return(item.sub and item.sub~="")and 2 or 1 end local sel=cfg.startIdx or 1 local scrollTop=1 local items=cfg.items or{}if#items==0 then return nil end sel=math.max(1,math.min(sel,#items))local function clampScroll(visH)while true do local ty=0 for i=scrollTop,#items do if i==sel then break end ty=ty+itemHeight(items[i])end if ty>=visH then scrollTop=scrollTop+1 else break end end while sel<scrollTop do scrollTop=scrollTop-1 end end local function drawMenu()local w,h=term.getSize()term.setBackgroundColor(colors.black)term.clear()local contentStart if cfg.showLogo then local logoH=drawLogo(1)contentStart=logoH+1 else local sepRow=1 term.setCursorPos(1,sepRow)term.setTextColor(colors.gray)term.clearLine()term.write(string.rep("=",w))local titleRow=sepRow+1 local title=cfg.title or""term.setCursorPos(1,titleRow)term.setTextColor(colors.red)term.clearLine()term.setCursorPos(math.max(1,math.floor((w-#title)/2)+1),titleRow)term.write(title)contentStart=titleRow+1 end if cfg.subtitle and cfg.subtitle~=""then local sub=cfg.subtitle term.setCursorPos(1,contentStart)term.setTextColor(colors.yellow)term.clearLine()term.setCursorPos(math.max(1,math.floor((w-#sub)/2)+1),contentStart)term.write(sub)contentStart=contentStart+1 end local FOOTER_H=2 local visH=h-contentStart-FOOTER_H+1 clampScroll(visH)local curY=contentStart for i=scrollTop,#items do if curY>h-FOOTER_H then break end local item=items[i]local label=item.label or tostring(i)local isSel=(i==sel)local maxLen=w-4 if#label>maxLen then label=label:sub(1,maxLen-1).."~"end term.setCursorPos(1,curY)term.setBackgroundColor(colors.black)term.clearLine()term.setCursorPos(2,curY)if isSel then term.setTextColor(colors.orange)term.write("> ")term.setTextColor(colors.yellow)else term.setTextColor(colors.gray)term.write("> ")term.setTextColor(colors.white)end term.write(label)curY=curY+1 if item.sub and item.sub~=""and curY<=h-FOOTER_H then local subStr=item.sub if#subStr>w-4 then subStr=subStr:sub(1,w-5).."~"end term.setCursorPos(1,curY)term.setTextColor(colors.lightGray)term.setBackgroundColor(colors.black)term.clearLine()term.setCursorPos(4,curY)term.write(subStr)curY=curY+1 end end term.setBackgroundColor(colors.black)while curY<=h-FOOTER_H do term.setCursorPos(1,curY)term.clearLine()curY=curY+1 end if scrollTop>1 then term.setCursorPos(w,contentStart)term.setTextColor(colors.gray)term.write("^")end local lastVisible,usedY=scrollTop,0 for i=scrollTop,#items do usedY=usedY+itemHeight(items[i])if usedY>=visH then lastVisible=i;break end lastVisible=i end if lastVisible<#items then term.setCursorPos(w,h-FOOTER_H)term.setTextColor(colors.gray)term.write("v")end local hint=cfg.footer or("UP/DN - Navigate  ENTER - Select"..(cfg.allowBack and"  ` - Back"or""))term.setCursorPos(1,h-1)term.setBackgroundColor(colors.black)term.setTextColor(colors.lightGray)term.clearLine()term.write(hint:sub(1,w))term.setCursorPos(1,h)term.clearLine()if cfg.footer2 then local f2=tostring(cfg.footer2)term.setTextColor(colors.gray)term.setCursorPos(w-#f2+1,h)term.write(f2)end end drawMenu()while true do local event,p1=os.pullEvent()if event=="key"then if p1==keys.up then sel=math.max(1,sel-1);drawMenu()elseif p1==keys.down then sel=math.min(#items,sel+1);drawMenu()elseif p1==keys.enter then return sel elseif p1==keys.grave and cfg.allowBack then return nil end elseif event=="term_resize"then drawMenu()end end end local LIST_W=26 function menu.showCharacterSelect()local sel=1 for _,char in ipairs(CHARACTERS)do loadImage(char.nfp)end loadImage("CCZombies/background.nfp")local function draw()local w,h=term.getSize()term.setBackgroundColor(colors.black)term.clear()local sepRow=1 term.setCursorPos(1,sepRow)term.setTextColor(colors.gray)term.write(string.rep("=",w))local titleRow=sepRow+1 local titleText="CHOOSE YOUR CHARACTER"term.setCursorPos(1,titleRow)term.setTextColor(colors.red)term.clearLine()term.setCursorPos(math.max(1,math.floor((LIST_W-#titleText)/2)+1),titleRow)term.write(titleText)local noteRow=titleRow+1 local noteText="(Singleplayer Only)"term.setCursorPos(1,noteRow)term.setTextColor(colors.lightGray)term.clearLine()term.setCursorPos(math.max(1,math.floor((LIST_W-#noteText)/2)+1),noteRow)term.write(noteText)local listStartY=noteRow+2 for i,char in ipairs(CHARACTERS)do local row=listStartY+(i-1)local isSel=(i==sel)term.setCursorPos(1,row)term.setBackgroundColor(colors.black)term.write(string.rep(" ",LIST_W))term.setCursorPos(2,row)if isSel then term.setTextColor(colors.orange)term.write(">")term.setTextColor(colors.yellow)else term.setTextColor(colors.gray)term.write(">")term.setTextColor(colors.white)end term.write(char.name)end term.setTextColor(colors.gray)for row=sepRow,h-2 do term.setCursorPos(LIST_W+1,row)term.write("|")end local bgImg=loadImage("CCZombies/background.nfp")if bgImg then local bgIndent=nfpIndent(bgImg)local bgRight=nfpRight(bgImg)local bgVisW=bgRight-bgIndent local bgX=w-bgVisW+1 local bgY=h-#bgImg-1 drawImage(bgImg,bgX,bgY,bgIndent)end local charImg=loadImage(CHARACTERS[sel].nfp)if charImg then local cIndent=nfpIndent(charImg)local cRight=nfpRight(charImg)local cVisW=cRight-cIndent local cX=w-cVisW+1 local cY=sepRow+1 drawImage(charImg,cX,cY,cIndent)end term.setCursorPos(1,h-1)term.setBackgroundColor(colors.black)term.setTextColor(colors.lightGray)term.clearLine()term.write(("UP/DN - Navigate  ENTER - Confirm  ` - Back"):sub(1,w))term.setCursorPos(1,h)term.clearLine()end draw()while true do local event,p1=os.pullEvent()if event=="key"then if p1==keys.up then sel=math.max(1,sel-1);draw()elseif p1==keys.down then sel=math.min(#CHARACTERS,sel+1);draw()elseif p1==keys.enter then return CHARACTERS[sel]elseif p1==keys.grave then return nil end elseif event=="term_resize"then draw()end end end function menu.showMainMenu()local ver="v"..(require("CCZombies.game").version or"?")local choice=scrollMenu({showLogo=true,allowBack=false,footer2=ver,items={{label="Play",sub="Singleplayer or Multiplayer"},{label="Character",sub="Choose your character"},{label="Settings",sub="Keybinds, display, audio, gameplay"},{label="Download Maps",sub="Get new CCZ maps via DLC"},{label="Test Features",sub="Developer / debug tools"},}})if choice==1 then return"play"elseif choice==2 then return"character"elseif choice==3 then return"settings"elseif choice==4 then return"maps"elseif choice==5 then return"test"end end function menu.showSettings(settingsModule)settingsModule.showMenu()end function menu.showPlayMenu()local choice=scrollMenu({title="PLAY",showLogo=false,allowBack=true,items={{label="Singleplayer",sub="Play solo"},{label="Multiplayer",sub="Play with friends"},}})if not choice then return"back"end if choice==1 then return"solo"elseif choice==2 then return"multiplayer"end end function menu.showMapDownload()scrollMenu({title="DOWNLOAD MAPS",subtitle="Coming soon...",showLogo=false,allowBack=true,items={{label="Back",sub="Return to main menu"}},})return"back"end function menu.showTestFeatures()scrollMenu({title="TEST FEATURES",subtitle="Developer tools coming soon...",showLogo=false,allowBack=true,items={{label="Back",sub="Return to main menu"}},})return"back"end menu.scrollMenu=scrollMenu menu.CHARACTERS=CHARACTERS return menu